/**
 * Writes scripts/data/rare-disease-market-research-saudi-arabia.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-rare-disease-ksa-research-cover.mjs.
 *
 *   node scripts/generate-rare-disease-ksa-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/rare-disease-market-research-saudi-arabia.json');

export const LAURA_MCCONAUGHEY_SANITY_ID = '5373a02d-e67d-4415-9739-33ee8f4da7e2';

/** Every blogPost field that applies to a healthcare-silo article. */
export const RARE_DISEASE_KSA_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-rare-disease-market-research-saudi-arabia.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.RARE_DISEASE_KSA_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.RARE_DISEASE_KSA_BODY_HTML.split('<h2')[0])
    .replace(/^Rare disease market research Saudi Arabia[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.RARE_DISEASE_KSA_META_TITLE,
      metaDescription: mod.RARE_DISEASE_KSA_META_DESCRIPTION,
      focusKeyword: 'rare disease market research Saudi Arabia',
      keywords: [
        'rare disease market research Saudi Arabia',
        'orphan drug market research Saudi Arabia',
        'SFDA NADR',
        'SFDA orphan drug designation',
        'NUPCO rare disease',
        'SMA market research Saudi Arabia',
        'cystic fibrosis Saudi Arabia',
        'rare disease market access Saudi Arabia',
      ],
      canonicalUrl: mod.RARE_DISEASE_KSA_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.RARE_DISEASE_KSA_META_TITLE,
      ogDescription: mod.RARE_DISEASE_KSA_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.RARE_DISEASE_KSA_COVER_IMAGE}`,
        alt: mod.RARE_DISEASE_KSA_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.RARE_DISEASE_KSA_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.RARE_DISEASE_KSA_SLUG },
    excerpt: mod.RARE_DISEASE_KSA_EXCERPT,
    publishedAt: mod.RARE_DISEASE_KSA_PUBLISHED_ISO,
    updatedAt: mod.RARE_DISEASE_KSA_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: LAURA_MCCONAUGHEY_SANITY_ID,
      name: 'Laura McConaughey',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.RARE_DISEASE_KSA_HERO_IMAGE}`,
      alt: mod.RARE_DISEASE_KSA_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for rare disease market research Saudi Arabia',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.RARE_DISEASE_KSA_TAGS],
    country: 'Saudi Arabia',
    language: 'en',
    readingTime: mod.RARE_DISEASE_KSA_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.RARE_DISEASE_KSA_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.RARE_DISEASE_KSA_EXECUTIVE_SUMMARY_HTML}\n\n${mod.RARE_DISEASE_KSA_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What rare disease market research Saudi Arabia should measure',
        type: 'table',
        data: JSON.stringify(
          mod.RARE_DISEASE_KSA_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'SFDA NADR 2026; Balkhi et al., 2023; AlJumah et al., 2022; Abu Esba et al., 2025; NUPCO NPT0045/25',
      },
      portableText(
        firstParagraph ||
          'Rare disease market research Saudi Arabia is a diagnosed-cohort and access problem before it is a sizing problem.',
      ),
    ],
    faq: mod.RARE_DISEASE_KSA_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['hematology-market-research-saudi-arabia', 'how-to-choose-healthcare-market-research-agency-saudi-arabia'],
    ctaSection: { ...mod.RARE_DISEASE_KSA_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.RARE_DISEASE_KSA_BODY_HTML),
    factCheckedAt: mod.RARE_DISEASE_KSA_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/rare-disease-market-research-saudi-arabia-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of RARE_DISEASE_KSA_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
